// The Larkspur Mobile catalog: parts, suppliers, products, open orders and
// quotes. Generated by scripts/phone_scenario.py into scenario/phones.json.
import scenario from "./scenario/phones.json";

export interface Part {
  part_no: string; description: string; hts10: string; supplier_id: string;
  unit_price_usd: number; products: string[]; annual_qty: number;
}
export interface Order {
  po_id: string; line_no: number; part_no: string; supplier_id: string; qty: number;
  unit_price_usd: number; customs_value_usd: number; est_entry_date: string;
  port: string | null; port_code: string | null;
}
export interface Supplier { name: string; country: string; country_code: string; city: string }

const catalog = scenario.catalog;
export const COMPANY = catalog.company;
export const PART_LIST: Part[] = catalog.parts;
export const PARTS: Record<string, Part> = Object.fromEntries(PART_LIST.map(part => [part.part_no, part]));
export const SUPPLIER_DIRECTORY: Record<string, Supplier> = catalog.suppliers;
export const PRODUCTS = catalog.products;
export const ORDERS: Order[] = catalog.orders;
export const QUOTES = catalog.quotes;
export const HEADINGS: Record<string, string> = catalog.headings;
export const BASE_RATES: Record<string, number> = catalog.base_rates;
export const AWARD = catalog.award;
export const ACTION_SUPPLIERS: Record<string, string> = catalog.action_suppliers;

export const partName = (partNo: string) => PARTS[partNo]?.description ?? partNo;
export const productName = (sku: string) => PRODUCTS.find(product => product.sku === sku)?.name ?? sku;
